-- =============================================================================
-- Forge Compatibility Profile V2 — calibrated 80-question catalog
--
-- Forward-only data migration:
--   * Preserves the V1 catalog and every V1 response.
--   * Creates the V2 catalog and makes it active.
--   * Eliminates priority follow-ups from the active product.
-- =============================================================================

set local lock_timeout = '5s';

update public.questionnaire_versions
set is_active = false
where is_active = true
  and version_key <> 'compatibility_profile_v2';

insert into public.questionnaire_versions (
  version_key, specification_version, title, is_active
) values (
  'compatibility_profile_v2',
  'compatibility_profile_calibrated_80_v1',
  'Compatibility Profile',
  true
)
on conflict (version_key) do update set
  specification_version = excluded.specification_version,
  title = excluded.title,
  is_active = excluded.is_active;

with data as (
  select *
  from jsonb_to_recordset($seed$[{"rule_key":"parenting_role_display_c07","description":"Display only when the user has children, wants or may want children, or is open to a future parenting or stepparenting role.","condition":{"type":"profile_predicate","predicateKey":"open_to_parenting_or_stepparenting_role"}},{"rule_key":"parenting_role_display_c08","description":"Display only when the user has children, wants or may want children, or is open to a future parenting or stepparenting role.","condition":{"type":"profile_predicate","predicateKey":"open_to_parenting_or_stepparenting_role"}},{"rule_key":"parenting_role_display_c09","description":"Display only when the user has children, wants or may want children, or is open to a future parenting or stepparenting role.","condition":{"type":"profile_predicate","predicateKey":"open_to_parenting_or_stepparenting_role"}}]$seed$::jsonb) as d(
    rule_key text,
    description text,
    condition jsonb
  )
)
insert into public.questionnaire_eligibility_rules (
  version_id, rule_key, description, condition
)
select v.id, d.rule_key, d.description, d.condition
from data d
cross join public.questionnaire_versions v
where v.version_key = 'compatibility_profile_v2'
on conflict (version_id, rule_key) do update set
  description = excluded.description,
  condition = excluded.condition;

