,"display_order":6},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","question_number":7,"prompt":"After a serious breach of trust, what should guide the next step?","statement":null,"format_label":"Trust repair posture with a separate context dependent state","response_behavior":"scale_range","context_note":"Forgiveness, reconciliation, continued participation in the relationship, and restored trust are separate decisions. None automatically requires the others.","implementation_note":"“The appropriate response depends…” is a separate context dependent state and should not be treated as a position on an ordered scale.\n\nThe remaining six responses should be stored as distinct trust repair postures rather than ranked from more forgiving to less forgiving.","eligibility_rule_key":null,"is_conditional":false,"select_all_that_apply":false,"structured_identity_config":null,"alignment_purpose":"Identifies the principle the respondent believes should carry the greatest influence after a serious breach while preserving the right to safety, boundaries, separation, and independent judgment.","min_selections":1,"max_selections":1,"allowed_special_response_states":["context_dependent"],"allowed_qualifiers":null,"display_order":7},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","question_number":8,"prompt":"Which trust or integrity problems could be dealbreakers?","statement":null,"format_label":"Select up to five","response_behavior":"multi_select","context_note":null,"implementation_note":null,"eligibility_rule_key":null,"is_conditional":false,"select_all_that_apply":false,"structured_identity_config":null,"alignment_purpose":"Identifies essential trust boundaries and high impact incompatibilities without assuming the respondent has experienced or engaged in the selected conduct.","min_selections":1,"max_selections":5,"allowed_special_response_states":null,"allowed_qualifiers":null,"display_order":8