rder":6,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q06","choice_key":"integrity_honesty_trust_q06_c07","label":"Some missed commitments are manageable when they do not involve essential responsibilities","display_order":7,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q06","choice_key":"integrity_honesty_trust_q06_c08","label":"An unresolved pattern may reveal a fundamental incompatibility","display_order":8,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","choice_key":"integrity_honesty_trust_q07_c01","label":"Trust may be rebuilt when there is full accountability, appropriate transparency, and sustained change","display_order":1,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","choice_key":"integrity_honesty_trust_q07_c02","label":"Trust may be rebuilt gradually through agreed boundaries and consistent behavior","display_order":2,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","choice_key":"integrity_honesty_trust_q07_c03","label":"The harmed partner should determine whether repair is possible and set its pace","display_order":3,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","choice_key":"integrity_honesty_trust_q07_c04","label":"Repair may include forgiveness, prayer, counseling, and firm boundaries","display_order":4,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","choice_key":"integrity_honesty_trust_q07_c05","label":"Forgiveness may be possible even when the relationship cannot continue","display_order":5,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","choice_key":"integrity_honesty_trust_q07_c06","label":"Some breaches permanently end the possibility of a safe or healthy relationship","display_order":6,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q07","choice_key":"integrity_honesty_trust_q07_c07","label":"The appropriate response depends on the nature, severity, pattern, and consequences of the breach","display_order":7,"mutually_exclusive":false,"special_response_state":"context_dependent","qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c01","label":"Repeated or deliberate lying about matters that affect the relationship","display_order":1,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c02","label":"Concealing another committed relationship or violating exclusivity agreements","display_order":2,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c03","label":"Hiding major financial, legal, health, substance related, or caregiving information that affects shared decisions","display_order":3,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c04","label":"Maintaining secret communications or relationships that violate agreed boundaries","display_order":4,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c05","label":"Manipulating facts to make me doubt my memory, perception, or judgment","display_order":5,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c06","label":"Blaming others or refusing responsibility after causing harm","display_order":6,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c07","label":"Repeatedly making commitments with no sincere effort to follow through","display_order":7,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null},{"category_key":"integrity_honesty_trust","question_key":"integrity_honesty_trust_q10","choice_key":"integrity_honesty_trust_q10_c08","label":"Using private information to shame, threaten, expose, or control me","display_order":8,"mutually_exclusive":false,"special_response_state":null,"qualifier":null,"qualifier_coexists_with_selections":false,"opens_optional_context":false,"optional_context_config":null}]$seed$::jsonb) as d(
    category_key text,
    question_key text,
    choice_key text,
    label text,
    display_order integer,
    mutually_exclusive boolean,
    special_response_state text,
    qualifier text,
    qualifier_coexists_with_selections boolean,
    opens_optional_context boolean,
    optional_context_config jsonb
  )
)
insert into public.questionnaire_answer_choices (
  question_id, choice_key, label, display_order, mutually_exclusive,
  special_response_state, qualifier, qualifier_coexists_with_selections,
  opens_optional_context, optional_context_config
)
select
  q.id,
  d.choice_key,
  d.label,
  d.display_order,
  d.mutually_exclusive,
  d.special_response_state::public.questionnaire_response_state,
  d.qualifier::public.questionnaire_response_qualifier,
  d.qualifier_coexists_with_selections,
  d.opens_optional_context,
  d.optional_context_config
from data d
join public.questionnaire_versions v
  on v.version_key = 'compatibility_profile_v2'
join public.questionnaire_categories c
  on c.version_id = v.id
 and c.category_key = d.category_key
join public.questionnaire_questions q
  on q.category_id = c.id
 and q.question_key = d.question_key
on conflict (question_id, choice_key) do update set
  label = excluded.label,
  display_order = excluded.display_order,
  mutually_exclusive = excluded.mutually_exclusive,
  special_response_state = excluded.special_response_state,
  qualifier = excluded.qualifier,
  qualifier_coexists_with_selections = excluded.qualifier_coexists_with_selections,
  opens_optional_context = excluded.opens_optional_context,
  optional_context_config = excluded.optional_context_config;

do $$
declare
  v_categories integer;
  v_questions integer;
  v_priorities integer;
begin
  select
    count(distinct c.id),
    count(distinct q.id),
    count(*) filter (where q.priority_follow_up_prompt is not null)
  into v_categories, v_questions, v_priorities
  from public.questionnaire_versions v
  join public.questionnaire_categories c on c.version_id = v.id
  join public.questionnaire_questions q on q.category_id = c.id
  where v.version_key = 'compatibility_profile_v2';

  if v_categories <> 10 or v_questions <> 80 or v_priorities <> 0 then
    raise exception
      'Compatibility Profile V2 contract failed: categories %, questions %, priorities %',
      v_categories, v_questions, v_priorities;
  end if;
end
$$;
